/* Pixel Shopping List - cohesive palette: #2b2b3c (bg), #f0e6d2 (card), #4a6fa5 (primary), #c44536 (accent), #6b8e5a (success) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #2b2b3c;
  color: #f0e6d2;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  image-rendering: pixelated;
}

.card {
  background: #f0e6d2;
  color: #2b2b3c;
  border: 4px solid #4a6fa5;
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 #1a1a2e;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 20px;
  text-align: center;
  letter-spacing: 1px;
  text-transform: uppercase;
  border-bottom: 3px dashed #4a6fa5;
  padding-bottom: 12px;
}

.add-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.input-group {
  display: flex;
  gap: 8px;
}

input[type="text"],
input[type="number"] {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 12px;
  border: 3px solid #4a6fa5;
  background: #fff;
  color: #2b2b3c;
  border-radius: 0;
  outline: none;
  transition: border-color 0.1s, box-shadow 0.1s;
}

input[type="text"] {
  flex: 1;
  min-width: 0;
}

input[type="number"] {
  width: 80px;
  text-align: center;
}

input:focus {
  border-color: #c44536;
  box-shadow: 0 0 0 3px rgba(196, 69, 54, 0.3);
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 20px;
  border: 3px solid #1a1a2e;
  border-radius: 0;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
  box-shadow: 4px 4px 0 #1a1a2e;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.btn:focus-visible {
  outline: 3px solid #c44536;
  outline-offset: 2px;
}

.btn.primary {
  background: #4a6fa5;
  color: #f0e6d2;
}

.btn.primary:hover {
  background: #3a5a8a;
}

.btn.secondary {
  background: #c44536;
  color: #f0e6d2;
}

.btn.secondary:hover {
  background: #a33a2e;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
  box-shadow: 4px 4px 0 #1a1a2e;
}

.shopping-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 24px;
  max-height: 300px;
  overflow-y: auto;
  padding-right: 4px;
}

.shopping-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: #fff;
  border: 3px solid #4a6fa5;
  transition: background 0.1s;
}

.shopping-list li.bought {
  background: #e0d8c8;
  border-color: #b0a890;
}

.shopping-list li.bought .item-text {
  text-decoration: line-through;
  opacity: 0.6;
}

.item-checkbox {
  width: 22px;
  height: 22px;
  accent-color: #6b8e5a;
  cursor: pointer;
  flex-shrink: 0;
}

.item-text {
  flex: 1;
  font-size: 1rem;
  word-break: break-word;
}

.item-qty {
  font-weight: 700;
  color: #4a6fa5;
  flex-shrink: 0;
}

.footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 3px dashed #4a6fa5;
  padding-top: 16px;
}

.remaining {
  font-weight: 700;
  font-size: 1rem;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .footer {
    flex-direction: column;
    align-items: stretch;
  }
  .footer .btn {
    width: 100%;
  }
}

(function () {
  'use strict';

  const form = document.getElementById('add-form');
  const nameInput = document.getElementById('item-name');
  const qtyInput = document.getElementById('item-qty');
  const list = document.getElementById('shopping-list');
  const remainingEl = document.getElementById('remaining-count');
  const clearBtn = document.getElementById('clear-bought');

  let items = [];
  let nextId = 1;

  function render() {
    list.innerHTML = '';
    const sorted = items.slice().sort((a, b) => {
      if (a.bought === b.bought) return a.id - b.id;
      return a.bought ? 1 : -1;
    });

    sorted.forEach(function (item) {
      const li = document.createElement('li');
      if (item.bought) li.classList.add('bought');

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.className = 'item-checkbox';
      checkbox.checked = item.bought;
      checkbox.setAttribute('aria-label', 'Mark ' + item.name + ' as bought');
      checkbox.addEventListener('change', function () {
        item.bought = checkbox.checked;
        render();
      });

      const text = document.createElement('span');
      text.className = 'item-text';
      text.textContent = item.name;

      const qty = document.createElement('span');
      qty.className = 'item-qty';
      qty.textContent = 'x' + item.qty;

      li.appendChild(checkbox);
      li.appendChild(text);
      li.appendChild(qty);
      list.appendChild(li);
    });

    const remaining = items.filter(function (i) { return !i.bought; }).length;
    remainingEl.textContent = remaining + (remaining === 1 ? ' item remaining' : ' items remaining');

    const hasBought = items.some(function (i) { return i.bought; });
    clearBtn.disabled = !hasBought;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    const name = nameInput.value.trim();
    const qty = parseInt(qtyInput.value, 10);
    if (!name || !qty || qty < 1) return;

    items.push({ id: nextId++, name: name, qty: qty, bought: false });
    nameInput.value = '';
    qtyInput.value = '1';
    nameInput.focus();
    render();
  });

  clearBtn.addEventListener('click', function () {
    items = items.filter(function (i) { return !i.bought; });
    render();
  });

  render();
})();
